const nodes=[...document.querySelectorAll('[data-t]')],alts=[...document.querySelectorAll('[data-alt]')];translations.ca=Object.fromEntries(nodes.map(el=>[el.dataset.t,el.innerHTML]));for(const el of alts)translations.ca[el.dataset.alt]=el.alt;translations.ca.description=document.querySelector('meta[name="description"]').content;
function setLanguage(lang){if(!translations[lang])lang='ca';const text=translations[lang];nodes.forEach(el=>el.innerHTML=text[el.dataset.t]);alts.forEach(el=>el.alt=text[el.dataset.alt]);document.documentElement.lang=lang;document.querySelector('meta[name="description"]').content=text.description;document.querySelector('nav').setAttribute('aria-label',{ca:'Navegació principal',es:'Navegación principal',en:'Main navigation'}[lang]);document.querySelectorAll('[data-lang]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.lang===lang)));const url=new URL(location.href);if(lang==='ca')url.searchParams.delete('lang');else url.searchParams.set('lang',lang);history.replaceState(null,'',url);}
document.querySelectorAll('[data-lang]').forEach(button=>button.addEventListener('click',()=>setLanguage(button.dataset.lang)));setLanguage(new URLSearchParams(location.search).get('lang')||'ca');
